// Loop through all incoming items
return $input.all().map(item => {
  try {
    // Parse the stringified JSON from the 'output' field
    const parsedData = JSON.parse(item.json.output);

    // Extract individual fields into separate variables
    return {
      json: {
        type: parsedData.type,
        text: parsedData.text,
        // Stores the full list of ideas as an array
        post_ideas: parsedData.post_idea, 
        // Optional: Extract specific ideas into separate fields if needed
        idea_1: parsedData.post_idea[0],
        idea_2: parsedData.post_idea[1],
        idea_3: parsedData.post_idea[2],
        idea_4: parsedData.post_idea[3]
      }
    };
  } catch (error) {
    // Return original item if parsing fails to avoid breaking the workflow
    return {
      json: {
        ...item.json,
        error: "Failed to parse JSON string: " + error.message
      }
    };
  }
});

// Loop over input items
for (const item of $input.all()) {
  try {
    // 1. Parse the inner JSON string stored in the 'output' field
    const innerData = JSON.parse(item.json.output);

    // 2. Separate all properties into individual fields on the item
    item.json.title = innerData.title;
    item.json.description = innerData.description;
    item.json.image_prompt = innerData.image_prompt;
    item.json.tags = innerData.tags;
    item.json.hashtags = innerData.hashtags;
    item.json.call_to_action = innerData.call_to_action;
    item.json.alt_text = innerData.alt_text;
    item.json.slug = innerData.slug;
    item.json.intent = innerData.intent;
    item.json.response = innerData.response;

    // Optional: Remove the original raw output string to clean up the data
    delete item.json.output;

  } catch (error) {
    // Handle potential JSON parsing errors gracefully
    item.json.error = "Failed to parse inner JSON: " + error.message;
  }
}

return $input.all();

const item = $input.first();

const data = item.json;

// Image Base64
const imageData =
  data.data ||
  data.image?.data ||
  data.imageBase64 ||
  data.base64 ||
  "";

// MIME type
const mimeType =
  data.mimeType ||
  data.image?.mimeType ||
  "image/png";

return [
  {
    json: {
      status: "complete",

      title: data.title || "",

      description: data.description || "",

      tags: Array.isArray(data.tags)
        ? data.tags
        : data.tags
          ? [data.tags]
          : [],

      hashtags: Array.isArray(data.hashtags)
        ? data.hashtags
        : data.hashtags
          ? [data.hashtags]
          : [],

      call_to_action: data.call_to_action || "",

      alt_text: data.alt_text || "",

      slug: data.slug || "",

      image: {
        data: imageData,
        mimeType: mimeType
      }
    }
  }
];
